import{_ as h,o as t,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Readiness khác Mastery thế nào","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/readiness-vs-mastery.md","filePath":"decisions/readiness-vs-mastery.md"}'),c={name:"decisions/readiness-vs-mastery.md"};function o(s,n,e,g,r,u){return t(),a("div",null,[...n[0]||(n[0]=[i('<h1 id="readiness-khac-mastery-the-nao" tabindex="-1">Readiness khác Mastery thế nào <a class="header-anchor" href="#readiness-khac-mastery-the-nao" aria-label="Permalink to &quot;Readiness khác Mastery thế nào&quot;">​</a></h1><p>Trên trang này# Readiness khác Mastery thế nào <a href="#readiness-khac-mastery-the-nao">​</a> Mastery trả lời: <strong>con giỏi tới đâu?</strong> Readiness trả lời: <strong>con còn cách mục tiêu này bao xa?</strong> Hai câu hỏi khác nhau, hai con số khác nhau, và chúng có thể lệch nhau rất nhiều mà không hề mâu thuẫn.</p><h2 id="cau-noi-khong-mau-thuan-​" tabindex="-1">Câu nói không mâu thuẫn <a href="#cau-noi-khong-mau-thuan">​</a> <a class="header-anchor" href="#cau-noi-khong-mau-thuan-​" aria-label="Permalink to &quot;Câu nói không mâu thuẫn [​](#cau-noi-khong-mau-thuan)&quot;">​</a></h2><p>&quot;Toán của con khá. Nhưng mức sẵn sàng cho kỳ thi chuyên đang thấp.&quot; Nghe như hai nhận xét đối nhau. Thật ra cả hai đều đúng, vì chúng đo hai thứ khác nhau:</p><ul><li><strong>Mastery</strong> đo so với chương trình phổ thông — và con vượt mức đó.</li><li><strong>Readiness</strong> đo so với <strong>một mục tiêu cụ thể</strong> — đề thi chuyên, dạng bài đó, độ sâu đó, ngày đó. Đề thi chuyên đòi hỏi mức sâu mà chương trình phổ thông không đòi. Giỏi ở chương trình chuẩn không tự động chuyển thành sẵn sàng cho một kỳ thi được thiết kế để phân loại.</li></ul><h2 id="readiness-luon-gan-voi-mot-đich-cu-the-​" tabindex="-1">Readiness luôn gắn với một đích cụ thể <a href="#readiness-luon-gan-voi-mot-đich-cu-the">​</a> <a class="header-anchor" href="#readiness-luon-gan-voi-mot-đich-cu-the-​" aria-label="Permalink to &quot;Readiness luôn gắn với một đích cụ thể [​](#readiness-luon-gan-voi-mot-đich-cu-the)&quot;">​</a></h2><p>Không có &quot;readiness&quot; chung chung. Luôn phải là &quot;readiness cho <strong>cái gì</strong>&quot;: Cùng một learner, cùng một ngày, có thể có ba con số readiness khác nhau: 0.82 cho kỳ thi học kỳ, 0.61 cho kỳ thi chuyên tháng 6, và 0.44 cho một chứng chỉ tiếng Anh — vì ba mục tiêu đó yêu cầu ba bộ kỹ năng ở ba mức sâu khác nhau.</p><h2 id="readiness-khong-chi-la-mot-con-so-​" tabindex="-1">Readiness không chỉ là một con số <a href="#readiness-khong-chi-la-mot-con-so">​</a> <a class="header-anchor" href="#readiness-khong-chi-la-mot-con-so-​" aria-label="Permalink to &quot;Readiness không chỉ là một con số [​](#readiness-khong-chi-la-mot-con-so)&quot;">​</a></h2><p>Nếu chỉ trả về 0.61 thì con số đó gần như vô dụng — biết mình còn 39% mà không biết 39% đó nằm ở đâu thì không hành động được. Readiness luôn kèm bốn thứ: textReadiness = 0.61 Các lỗ hổng chính: Hình học cần 0.85 · hiện 0.52 · thiếu 0.33 Số học cần 0.80 · hiện 0.61 · thiếu 0.19 Chỗ chưa chắc chắn nhất: Tổ hợp — chỉ có 2 bằng chứng, chưa đủ để nói gì Nên đo tiếp cái gì:</p><ol><li>Tổ hợp (chưa biết đủ)</li><li>Hình học không gian (bằng chứng cũ)Mục &quot;chỗ chưa chắc chắn nhất&quot; là mục hay bị bỏ qua nhưng quan trọng nhất. Nó phân biệt hai tình huống rất khác nhau: <em>&quot;con yếu phần này&quot;</em> và <em>&quot;tôi không biết con thế nào ở phần này&quot;</em>. Cái thứ hai cần đo, không cần học.</li></ol><h2 id="ba-con-so-ba-cau-hoi-​" tabindex="-1">Ba con số, ba câu hỏi <a href="#ba-con-so-ba-cau-hoi">​</a> <a class="header-anchor" href="#ba-con-so-ba-cau-hoi-​" aria-label="Permalink to &quot;Ba con số, ba câu hỏi [​](#ba-con-so-ba-cau-hoi)&quot;">​</a></h2><p>Con sốCâu hỏiCó giảm theo thời gian không<strong>Mastery</strong>Con đã đạt tới mức nào?<strong>Không</strong> — là sự thật lịch sử<strong>Retention</strong>Con còn nhớ và dùng được không?<strong>Có</strong> — mờ dần nếu không dùng<strong>Readiness</strong>Còn cách mục tiêu này bao xa?Đổi khi mục tiêu, thời gian, hoặc trí nhớ đổiBa chiều đo độc lập. Một learner có thể có mastery 0.90 (từng rất giỏi), retention 0.55 (tám tháng chưa đụng tới), và readiness 0.40 cho một kỳ thi tháng sau. Cả ba con số đều đúng, và chúng cùng nhau kể một câu chuyện mà một con số duy nhất không kể được: <strong>kiến thức có sẵn trong đầu, chỉ cần đánh thức, và còn kịp thời gian</strong>. Nếu chỉ có một con số 0.40, phản ứng hợp lý sẽ là hoảng và bắt đầu học lại từ đầu — một phản ứng sai và tốn kém.</p><h2 id="vi-sao-readiness-đoi-ma-con-khong-lam-gi-ca-​" tabindex="-1">Vì sao readiness đổi mà con không làm gì cả <a href="#vi-sao-readiness-đoi-ma-con-khong-lam-gi-ca">​</a> <a class="header-anchor" href="#vi-sao-readiness-đoi-ma-con-khong-lam-gi-ca-​" aria-label="Permalink to &quot;Vì sao readiness đổi mà con không làm gì cả [​](#vi-sao-readiness-đoi-ma-con-khong-lam-gi-ca)&quot;">​</a></h2><p>Bốn lý do, đều hợp lệ: <strong>Ngày thi đổi.</strong> Dời gần lại thì mức khẩn tăng, readiness so với thời gian còn lại giảm. <strong>Mục tiêu đổi.</strong> Gia đình chốt thi chuyên thay vì thi thường — yêu cầu cao hơn, readiness tụt ngay lập tức dù learner không thay đổi gì. <strong>Trí nhớ mờ đi.</strong> Không dùng thì retention giảm, kéo readiness xuống theo. <strong>Hệ thống biết thêm.</strong> Một bài đo mới làm rõ một chỗ trước đây chưa chắc — readiness được tính lại chính xác hơn, có thể lên hoặc xuống. Trong cả bốn trường hợp, hệ thống ghi rõ <strong>lý do</strong>. Đặc biệt, một readiness giảm do trí nhớ mờ được ghi là <em>&quot;do ước lượng quên&quot;</em>, không phải <em>&quot;do kết quả sa sút&quot;</em> — hai điều rất khác nhau, và cách xử lý cũng khác nhau hoàn toàn.</p><h2 id="đieu-nay-dung-đuoc-the-nao-​" tabindex="-1">Điều này dùng được thế nào <a href="#đieu-nay-dung-đuoc-the-nao">​</a> <a class="header-anchor" href="#đieu-nay-dung-đuoc-the-nao-​" aria-label="Permalink to &quot;Điều này dùng được thế nào [​](#đieu-nay-dung-đuoc-the-nao)&quot;">​</a></h2><p>Khi bạn nhìn vào một mục tiêu của con, ba câu hỏi đáng hỏi theo thứ tự:</p><ul><li><strong>Còn thiếu ở đâu?</strong> — danh sách lỗ hổng chính.</li><li><strong>Chỗ nào đang chỉ là phỏng đoán?</strong> — chỗ chưa chắc chắn nhất; đo trước khi lo.</li><li><strong>Còn bao nhiêu thời gian, và mức thiếu đó có kịp không?</strong> — nếu không kịp, đây là lúc điều chỉnh mốc, không phải lúc tăng giờ học lên gấp đôi. Mastery nói về con. Readiness nói về khoảng cách giữa con và một cái đích cụ thể. Đổi đích thì khoảng cách đổi — dù đứa trẻ không đổi gì cả. <a href="/decisions/retention">Quên và ôn tập ảnh hưởng gợi ý ra sao →</a></li></ul>',17)])])}const d=h(c,[["render",o]]);export{m as __pageData,d as default};
